window.CODES={"1": {"C#": "using System;\nusing System.Collections.Generic;\npublic class Solution {\n    public int[] TwoSum(int[] nums, int target) {\n        var seen = new Dictionary<int, int>();\n        for (int i = 0; i < nums.Length; i++) {\n            int need = target - nums[i];\n            if (seen.TryGetValue(need, out int j))\n                return new[] { j, i };\n            seen[nums[i]] = i;\n        }\n        return Array.Empty<int>();\n    }\n}", "Python": "def two_sum(nums: list[int], target: int) -> list[int]:\n    seen = {}\n    for i, value in enumerate(nums):\n        need = target - value\n        if need in seen:\n            return [seen[need], i]\n        seen[value] = i\n    return []", "Java": "import java.util.HashMap;\nimport java.util.Map;\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        Map<Integer, Integer> seen = new HashMap<>();\n        for (int i = 0; i < nums.length; i++) {\n            int need = target - nums[i];\n            if (seen.containsKey(need))\n                return new int[]{seen.get(need), i};\n            seen.put(nums[i], i);\n        }\n        return new int[0];\n    }\n}", "JavaScript（Node.js）": "function twoSum(nums, target) {\n    const seen = new Map();\n    for (let i = 0; i < nums.length; i++) {\n        const need = target - nums[i];\n        if (seen.has(need)) return [seen.get(need), i];\n        seen.set(nums[i], i);\n    }\n    return [];\n}", "TypeScript": "function twoSum(nums: number[], target: number): number[] {\n    const seen = new Map<number, number>();\n    for (let i = 0; i < nums.length; i++) {\n        const need = target - nums[i];\n        if (seen.has(need)) return [seen.get(need)!, i];\n        seen.set(nums[i], i);\n    }\n    return [];\n}"}, "3": {"C#": "using System.Collections.Generic;\npublic class Solution {\n    public int LengthOfLongestSubstring(string s) {\n        var seen = new HashSet<char>();\n        int left = 0, best = 0;\n        for (int right = 0; right < s.Length; right++) {\n            while (seen.Contains(s[right])) {\n                seen.Remove(s[left]); left++;\n            }\n            seen.Add(s[right]);\n            int length = right - left + 1;\n            if (length > best) best = length;\n        }\n        return best;\n    }\n}", "Python": "def length_of_longest_substring(s: str) -> int:\n    seen = set()\n    left = best = 0\n    for right in range(len(s)):\n        while s[right] in seen:\n            seen.remove(s[left])\n            left += 1\n        seen.add(s[right])\n        length = right - left + 1\n        if length > best:\n            best = length\n    return best", "Java": "import java.util.HashSet;\nimport java.util.Set;\nclass Solution {\n    public int lengthOfLongestSubstring(String s) {\n        Set<Character> seen = new HashSet<>();\n        int left = 0, best = 0;\n        for (int right = 0; right < s.length(); right++) {\n            while (seen.contains(s.charAt(right))) {\n                seen.remove(s.charAt(left)); left++;\n            }\n            seen.add(s.charAt(right));\n            int length = right - left + 1;\n            if (length > best) best = length;\n        }\n        return best;\n    }\n}", "JavaScript（Node.js）": "function lengthOfLongestSubstring(s) {\n    const seen = new Set();\n    let left = 0, best = 0;\n    for (let right = 0; right < s.length; right++) {\n        while (seen.has(s[right])) { seen.delete(s[left]); left++; }\n        seen.add(s[right]);\n        const length = right - left + 1;\n        if (length > best) best = length;\n    }\n    return best;\n}", "TypeScript": "function lengthOfLongestSubstring(s: string): number {\n    const seen = new Set<string>();\n    let left = 0, best = 0;\n    for (let right = 0; right < s.length; right++) {\n        while (seen.has(s[right])) { seen.delete(s[left]); left++; }\n        seen.add(s[right]);\n        const length = right - left + 1;\n        if (length > best) best = length;\n    }\n    return best;\n}"}, "20": {"C#": "using System.Collections.Generic;\npublic class Solution {\n    public bool IsValid(string s) {\n        var stack = new Stack<char>();\n        var pairs = new Dictionary<char, char> {\n            { ')', '(' }, { ']', '[' }, { '}', '{' }\n        };\n        foreach (char c in s) {\n            if (pairs.ContainsKey(c)) {\n                if (stack.Count == 0 || stack.Peek() != pairs[c])\n                    return false;\n                stack.Pop();\n            } else stack.Push(c);\n        }\n        return stack.Count == 0;\n    }\n}", "Python": "def is_valid(s: str) -> bool:\n    stack = []\n    pairs = {')': '(', ']': '[', '}': '{'}\n    for char in s:\n        if char in pairs:\n            if not stack or stack[-1] != pairs[char]:\n                return False\n            stack.pop()\n        else:\n            stack.append(char)\n    return not stack", "Java": "import java.util.ArrayDeque;\nimport java.util.Deque;\nimport java.util.Map;\nclass Solution {\n    public boolean isValid(String s) {\n        Deque<Character> stack = new ArrayDeque<>();\n        Map<Character, Character> pairs = Map.of(\n            ')', '(', ']', '[', '}', '{');\n        for (char c : s.toCharArray()) {\n            if (pairs.containsKey(c)) {\n                if (stack.isEmpty() || stack.peek() != pairs.get(c).charValue())\n                    return false;\n                stack.pop();\n            } else stack.push(c);\n        }\n        return stack.isEmpty();\n    }\n}", "JavaScript（Node.js）": "function isValid(s) {\n    const stack = [];\n    const pairs = { ')': '(', ']': '[', '}': '{' };\n    for (const c of s) {\n        if (Object.hasOwn(pairs, c)) {\n            if (!stack.length || stack[stack.length - 1] !== pairs[c])\n                return false;\n            stack.pop();\n        } else stack.push(c);\n    }\n    return stack.length === 0;\n}", "TypeScript": "function isValid(s: string): boolean {\n    const stack: string[] = [];\n    const pairs: Record<string, string> = { ')': '(', ']': '[', '}': '{' };\n    for (const c of s) {\n        if (Object.hasOwn(pairs, c)) {\n            if (!stack.length || stack[stack.length - 1] !== pairs[c])\n                return false;\n            stack.pop();\n        } else stack.push(c);\n    }\n    return stack.length === 0;\n}"}, "21": {"C#": "public class ListNode {\n    public int val; public ListNode next;\n    public ListNode(int val = 0, ListNode next = null) { this.val = val; this.next = next; }\n}\npublic class Solution {\n    public ListNode MergeTwoLists(ListNode a, ListNode b) {\n        ListNode dummy = new ListNode(), tail = dummy;\n        while (a != null && b != null) {\n            if (a.val <= b.val) { tail.next = a; a = a.next; }\n            else { tail.next = b; b = b.next; }\n            tail = tail.next;\n        }\n        tail.next = a != null ? a : b;\n        return dummy.next;\n    }\n}", "Python": "class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val, self.next = val, next\n\ndef merge_two_lists(a, b):\n    dummy = ListNode()\n    tail = dummy\n    while a is not None and b is not None:\n        if a.val <= b.val:\n            tail.next, a = a, a.next\n        else:\n            tail.next, b = b, b.next\n        tail = tail.next\n    tail.next = a if a is not None else b\n    return dummy.next", "Java": "class ListNode {\n    int val; ListNode next;\n    ListNode(int val) { this.val = val; }\n}\nclass Solution {\n    public ListNode mergeTwoLists(ListNode a, ListNode b) {\n        ListNode dummy = new ListNode(0), tail = dummy;\n        while (a != null && b != null) {\n            if (a.val <= b.val) { tail.next = a; a = a.next; }\n            else { tail.next = b; b = b.next; }\n            tail = tail.next;\n        }\n        tail.next = a != null ? a : b;\n        return dummy.next;\n    }\n}", "JavaScript（Node.js）": "class ListNode {\n    constructor(val = 0, next = null) { this.val = val; this.next = next; }\n}\nfunction mergeTwoLists(a, b) {\n    const dummy = new ListNode(); let tail = dummy;\n    while (a !== null && b !== null) {\n        if (a.val <= b.val) { tail.next = a; a = a.next; }\n        else { tail.next = b; b = b.next; }\n        tail = tail.next;\n    }\n    tail.next = a !== null ? a : b;\n    return dummy.next;\n}", "TypeScript": "class ListNode {\n    val: number; next: ListNode | null;\n    constructor(val = 0, next: ListNode | null = null) { this.val = val; this.next = next; }\n}\nfunction mergeTwoLists(a: ListNode | null, b: ListNode | null): ListNode | null {\n    const dummy = new ListNode(); let tail = dummy;\n    while (a !== null && b !== null) {\n        if (a.val <= b.val) { tail.next = a; a = a.next; }\n        else { tail.next = b; b = b.next; }\n        tail = tail.next;\n    }\n    tail.next = a !== null ? a : b;\n    return dummy.next;\n}"}, "26": {"C#": "public class Solution {\n    public int RemoveDuplicates(int[] nums) {\n        if (nums.Length == 0) return 0;\n        int write = 1;\n        for (int read = 1; read < nums.Length; read++) {\n            if (nums[read] != nums[write - 1]) {\n                nums[write] = nums[read];\n                write++;\n            }\n        }\n        return write;\n    }\n}", "Python": "def remove_duplicates(nums: list[int]) -> int:\n    if not nums:\n        return 0\n    write = 1\n    for read in range(1, len(nums)):\n        if nums[read] != nums[write - 1]:\n            nums[write] = nums[read]\n            write += 1\n    return write", "Java": "class Solution {\n    public int removeDuplicates(int[] nums) {\n        if (nums.length == 0) return 0;\n        int write = 1;\n        for (int read = 1; read < nums.length; read++) {\n            if (nums[read] != nums[write - 1]) {\n                nums[write] = nums[read];\n                write++;\n            }\n        }\n        return write;\n    }\n}", "JavaScript（Node.js）": "function removeDuplicates(nums) {\n    if (nums.length === 0) return 0;\n    let write = 1;\n    for (let read = 1; read < nums.length; read++) {\n        if (nums[read] !== nums[write - 1]) {\n            nums[write] = nums[read];\n            write++;\n        }\n    }\n    return write;\n}", "TypeScript": "function removeDuplicates(nums: number[]): number {\n    if (nums.length === 0) return 0;\n    let write = 1;\n    for (let read = 1; read < nums.length; read++) {\n        if (nums[read] !== nums[write - 1]) {\n            nums[write] = nums[read];\n            write++;\n        }\n    }\n    return write;\n}"}, "35": {"C#": "public class Solution {\n    public int SearchInsert(int[] nums, int target) {\n        int left = 0, right = nums.Length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) return mid;\n            if (nums[mid] < target) left = mid + 1;\n            else right = mid - 1;\n        }\n        return left;\n    }\n}", "Python": "def search_insert(nums: list[int], target: int) -> int:\n    left, right = 0, len(nums) - 1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] == target:\n            return mid\n        if nums[mid] < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return left", "Java": "class Solution {\n    public int searchInsert(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) return mid;\n            if (nums[mid] < target) left = mid + 1;\n            else right = mid - 1;\n        }\n        return left;\n    }\n}", "JavaScript（Node.js）": "function searchInsert(nums, target) {\n    let left = 0, right = nums.length - 1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) return mid;\n        if (nums[mid] < target) left = mid + 1;\n        else right = mid - 1;\n    }\n    return left;\n}", "TypeScript": "function searchInsert(nums: number[], target: number): number {\n    let left = 0, right = nums.length - 1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) return mid;\n        if (nums[mid] < target) left = mid + 1;\n        else right = mid - 1;\n    }\n    return left;\n}"}, "104": {"C#": "using System.Collections.Generic;\npublic class TreeNode {\n    public int val;\n    public TreeNode left, right;\n    public TreeNode(int val = 0, TreeNode left = null, TreeNode right = null) {\n        this.val = val; this.left = left; this.right = right;\n    }\n}\npublic class Solution {\n    public int MaxDepth(TreeNode root) {\n        if (root == null) return 0;\n        var queue = new Queue<TreeNode>();\n        queue.Enqueue(root);\n        int depth = 0;\n        while (queue.Count > 0) {\n            int size = queue.Count;\n            depth++;\n            for (int i = 0; i < size; i++) {\n                TreeNode node = queue.Dequeue();\n                if (node.left != null) queue.Enqueue(node.left);\n                if (node.right != null) queue.Enqueue(node.right);\n            }\n        }\n        return depth;\n    }\n}", "Python": "from collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val, self.left, self.right = val, left, right\n\ndef max_depth(root: TreeNode | None) -> int:\n    if root is None:\n        return 0\n    queue = deque([root])\n    depth = 0\n    while queue:\n        size = len(queue)\n        depth += 1\n        for _ in range(size):\n            node = queue.popleft()\n            if node.left is not None:\n                queue.append(node.left)\n            if node.right is not None:\n                queue.append(node.right)\n    return depth", "Java": "import java.util.ArrayDeque;\nimport java.util.Queue;\nclass TreeNode {\n    int val;\n    TreeNode left, right;\n    TreeNode(int val) { this.val = val; }\n}\nclass Solution {\n    public int maxDepth(TreeNode root) {\n        if (root == null) return 0;\n        Queue<TreeNode> queue = new ArrayDeque<>();\n        queue.add(root);\n        int depth = 0;\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            depth++;\n            for (int i = 0; i < size; i++) {\n                TreeNode node = queue.remove();\n                if (node.left != null) queue.add(node.left);\n                if (node.right != null) queue.add(node.right);\n            }\n        }\n        return depth;\n    }\n}", "JavaScript（Node.js）": "class TreeNode {\n    constructor(val = 0, left = null, right = null) {\n        this.val = val; this.left = left; this.right = right;\n    }\n}\nfunction maxDepth(root) {\n    if (root === null) return 0;\n    const queue = [root];\n    let head = 0, depth = 0;\n    while (head < queue.length) {\n        const levelEnd = queue.length;\n        depth++;\n        while (head < levelEnd) {\n            const node = queue[head++];\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n    }\n    return depth;\n}", "TypeScript": "class TreeNode {\n    val: number;\n    left: TreeNode | null;\n    right: TreeNode | null;\n    constructor(val = 0, left: TreeNode | null = null, right: TreeNode | null = null) {\n        this.val = val; this.left = left; this.right = right;\n    }\n}\nfunction maxDepth(root: TreeNode | null): number {\n    if (root === null) return 0;\n    const queue: TreeNode[] = [root];\n    let head = 0, depth = 0;\n    while (head < queue.length) {\n        const levelEnd = queue.length;\n        depth++;\n        while (head < levelEnd) {\n            const node = queue[head++];\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n    }\n    return depth;\n}"}, "121": {"C#": "public class Solution {\n    public int MaxProfit(int[] prices) {\n        if (prices.Length == 0) return 0;\n        int minimum = prices[0], best = 0;\n        for (int day = 1; day < prices.Length; day++) {\n            int profit = prices[day] - minimum;\n            if (profit > best) best = profit;\n            if (prices[day] < minimum) minimum = prices[day];\n        }\n        return best;\n    }\n}", "Python": "def max_profit(prices: list[int]) -> int:\n    if not prices:\n        return 0\n    minimum, best = prices[0], 0\n    for day in range(1, len(prices)):\n        profit = prices[day] - minimum\n        if profit > best:\n            best = profit\n        if prices[day] < minimum:\n            minimum = prices[day]\n    return best", "Java": "class Solution {\n    public int maxProfit(int[] prices) {\n        if (prices.length == 0) return 0;\n        int minimum = prices[0], best = 0;\n        for (int day = 1; day < prices.length; day++) {\n            int profit = prices[day] - minimum;\n            if (profit > best) best = profit;\n            if (prices[day] < minimum) minimum = prices[day];\n        }\n        return best;\n    }\n}", "JavaScript（Node.js）": "function maxProfit(prices) {\n    if (prices.length === 0) return 0;\n    let minimum = prices[0], best = 0;\n    for (let day = 1; day < prices.length; day++) {\n        const profit = prices[day] - minimum;\n        if (profit > best) best = profit;\n        if (prices[day] < minimum) minimum = prices[day];\n    }\n    return best;\n}", "TypeScript": "function maxProfit(prices: number[]): number {\n    if (prices.length === 0) return 0;\n    let minimum = prices[0], best = 0;\n    for (let day = 1; day < prices.length; day++) {\n        const profit = prices[day] - minimum;\n        if (profit > best) best = profit;\n        if (prices[day] < minimum) minimum = prices[day];\n    }\n    return best;\n}"}, "125": {"C#": "public class Solution {\n    private bool IsAscii(char c) => (c >= 'a' && c <= 'z') ||\n        (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');\n    public bool IsPalindrome(string s) {\n        int left = 0, right = s.Length - 1;\n        while (left < right) {\n            if (!IsAscii(s[left])) { left++; continue; }\n            if (!IsAscii(s[right])) { right--; continue; }\n            if (char.ToLowerInvariant(s[left]) != char.ToLowerInvariant(s[right]))\n                return false;\n            left++; right--;\n        }\n        return true;\n    }\n}", "Python": "def is_palindrome(s: str) -> bool:\n    def valid(c: str) -> bool:\n        return ('a' <= c <= 'z' or 'A' <= c <= 'Z' or '0' <= c <= '9')\n    left, right = 0, len(s) - 1\n    while left < right:\n        if not valid(s[left]):\n            left += 1\n            continue\n        if not valid(s[right]):\n            right -= 1\n            continue\n        if s[left].lower() != s[right].lower():\n            return False\n        left += 1\n        right -= 1\n    return True", "Java": "class Solution {\n    private boolean valid(char c) {\n        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||\n            (c >= '0' && c <= '9');\n    }\n    public boolean isPalindrome(String s) {\n        int left = 0, right = s.length() - 1;\n        while (left < right) {\n            if (!valid(s.charAt(left))) { left++; continue; }\n            if (!valid(s.charAt(right))) { right--; continue; }\n            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right)))\n                return false;\n            left++; right--;\n        }\n        return true;\n    }\n}", "JavaScript（Node.js）": "function isPalindrome(s) {\n    const valid = c => /[A-Za-z0-9]/.test(c);\n    let left = 0, right = s.length - 1;\n    while (left < right) {\n        if (!valid(s[left])) { left++; continue; }\n        if (!valid(s[right])) { right--; continue; }\n        if (s[left].toLowerCase() !== s[right].toLowerCase()) return false;\n        left++; right--;\n    }\n    return true;\n}", "TypeScript": "function isPalindrome(s: string): boolean {\n    const valid = (c: string): boolean => /[A-Za-z0-9]/.test(c);\n    let left = 0, right = s.length - 1;\n    while (left < right) {\n        if (!valid(s[left])) { left++; continue; }\n        if (!valid(s[right])) { right--; continue; }\n        if (s[left].toLowerCase() !== s[right].toLowerCase()) return false;\n        left++; right--;\n    }\n    return true;\n}"}, "167": {"C#": "public class Solution {\n    public int[] TwoSum(int[] numbers, int target) {\n        int left = 0, right = numbers.Length - 1;\n        while (left < right) {\n            int sum = numbers[left] + numbers[right];\n            if (sum == target) return new int[]{left + 1, right + 1};\n            if (sum < target) left++; else right--;\n        }\n        return new int[0];\n    }\n}", "Python": "def two_sum_sorted(numbers: list[int], target: int) -> list[int]:\n    left, right = 0, len(numbers) - 1\n    while left < right:\n        total = numbers[left] + numbers[right]\n        if total == target:\n            return [left + 1, right + 1]\n        if total < target:\n            left += 1\n        else:\n            right -= 1\n    return []", "Java": "class Solution {\n    public int[] twoSum(int[] numbers, int target) {\n        int left = 0, right = numbers.length - 1;\n        while (left < right) {\n            int sum = numbers[left] + numbers[right];\n            if (sum == target) return new int[]{left + 1, right + 1};\n            if (sum < target) left++; else right--;\n        }\n        return new int[0];\n    }\n}", "JavaScript（Node.js）": "function twoSumSorted(numbers, target) {\n    let left = 0, right = numbers.length - 1;\n    while (left < right) {\n        const sum = numbers[left] + numbers[right];\n        if (sum === target) return [left + 1, right + 1];\n        if (sum < target) left++; else right--;\n    }\n    return [];\n}", "TypeScript": "function twoSumSorted(numbers: number[], target: number): number[] {\n    let left = 0, right = numbers.length - 1;\n    while (left < right) {\n        const sum = numbers[left] + numbers[right];\n        if (sum === target) return [left + 1, right + 1];\n        if (sum < target) left++; else right--;\n    }\n    return [];\n}"}, "206": {"C#": "public class ListNode {\n    public int val;\n    public ListNode next;\n    public ListNode(int val = 0, ListNode next = null) { this.val = val; this.next = next; }\n}\npublic class Solution {\n    public ListNode ReverseList(ListNode head) {\n        ListNode previous = null, current = head;\n        while (current != null) {\n            ListNode nextSaved = current.next;\n            current.next = previous;\n            previous = current;\n            current = nextSaved;\n        }\n        return previous;\n    }\n}", "Python": "class ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef reverse_list(head: ListNode | None) -> ListNode | None:\n    previous, current = None, head\n    while current is not None:\n        next_saved = current.next\n        current.next = previous\n        previous = current\n        current = next_saved\n    return previous", "Java": "class ListNode {\n    int val;\n    ListNode next;\n    ListNode(int val) { this.val = val; }\n}\nclass Solution {\n    public ListNode reverseList(ListNode head) {\n        ListNode previous = null, current = head;\n        while (current != null) {\n            ListNode nextSaved = current.next;\n            current.next = previous;\n            previous = current;\n            current = nextSaved;\n        }\n        return previous;\n    }\n}", "JavaScript（Node.js）": "class ListNode {\n    constructor(val = 0, next = null) { this.val = val; this.next = next; }\n}\nfunction reverseList(head) {\n    let previous = null, current = head;\n    while (current !== null) {\n        const nextSaved = current.next;\n        current.next = previous;\n        previous = current;\n        current = nextSaved;\n    }\n    return previous;\n}", "TypeScript": "class ListNode {\n    val: number;\n    next: ListNode | null;\n    constructor(val = 0, next: ListNode | null = null) { this.val = val; this.next = next; }\n}\nfunction reverseList(head: ListNode | null): ListNode | null {\n    let previous: ListNode | null = null, current = head;\n    while (current !== null) {\n        const nextSaved: ListNode | null = current.next;\n        current.next = previous;\n        previous = current;\n        current = nextSaved;\n    }\n    return previous;\n}"}, "217": {"C#": "using System.Collections.Generic;\npublic class Solution {\n    public bool ContainsDuplicate(int[] nums) {\n        var seen = new HashSet<int>();\n        foreach (int value in nums) {\n            if (seen.Contains(value)) return true;\n            seen.Add(value);\n        }\n        return false;\n    }\n}", "Python": "def contains_duplicate(nums: list[int]) -> bool:\n    seen = set()\n    for value in nums:\n        if value in seen:\n            return True\n        seen.add(value)\n    return False", "Java": "import java.util.HashSet;\nimport java.util.Set;\nclass Solution {\n    public boolean containsDuplicate(int[] nums) {\n        Set<Integer> seen = new HashSet<>();\n        for (int value : nums) {\n            if (seen.contains(value)) return true;\n            seen.add(value);\n        }\n        return false;\n    }\n}", "JavaScript（Node.js）": "function containsDuplicate(nums) {\n    const seen = new Set();\n    for (const value of nums) {\n        if (seen.has(value)) return true;\n        seen.add(value);\n    }\n    return false;\n}", "TypeScript": "function containsDuplicate(nums: number[]): boolean {\n    const seen = new Set<number>();\n    for (const value of nums) {\n        if (seen.has(value)) return true;\n        seen.add(value);\n    }\n    return false;\n}"}, "219": {"C#": "using System.Collections.Generic;\npublic class Solution {\n    public bool ContainsNearbyDuplicate(int[] nums, int k) {\n        if (k <= 0) return false;\n        var seen = new HashSet<int>();\n        for (int i = 0; i < nums.Length; i++) {\n            if (seen.Contains(nums[i])) return true;\n            seen.Add(nums[i]);\n            if (i >= k) seen.Remove(nums[i - k]);\n        }\n        return false;\n    }\n}", "Python": "def contains_nearby_duplicate(nums: list[int], k: int) -> bool:\n    if k <= 0:\n        return False\n    seen = set()\n    for i in range(len(nums)):\n        if nums[i] in seen:\n            return True\n        seen.add(nums[i])\n        if i >= k:\n            seen.remove(nums[i - k])\n    return False", "Java": "import java.util.HashSet;\nimport java.util.Set;\nclass Solution {\n    public boolean containsNearbyDuplicate(int[] nums, int k) {\n        if (k <= 0) return false;\n        Set<Integer> seen = new HashSet<>();\n        for (int i = 0; i < nums.length; i++) {\n            if (seen.contains(nums[i])) return true;\n            seen.add(nums[i]);\n            if (i >= k) seen.remove(nums[i - k]);\n        }\n        return false;\n    }\n}", "JavaScript（Node.js）": "function containsNearbyDuplicate(nums, k) {\n    if (k <= 0) return false;\n    const seen = new Set();\n    for (let i = 0; i < nums.length; i++) {\n        if (seen.has(nums[i])) return true;\n        seen.add(nums[i]);\n        if (i >= k) seen.delete(nums[i - k]);\n    }\n    return false;\n}", "TypeScript": "function containsNearbyDuplicate(nums: number[], k: number): boolean {\n    if (k <= 0) return false;\n    const seen = new Set<number>();\n    for (let i = 0; i < nums.length; i++) {\n        if (seen.has(nums[i])) return true;\n        seen.add(nums[i]);\n        if (i >= k) seen.delete(nums[i - k]);\n    }\n    return false;\n}"}, "283": {"C#": "public class Solution {\n    public void MoveZeroes(int[] nums) {\n        int write = 0;\n        for (int read = 0; read < nums.Length; read++) {\n            if (nums[read] != 0) {\n                nums[write] = nums[read];\n                write++;\n            }\n        }\n        for (int i = write; i < nums.Length; i++) nums[i] = 0;\n    }\n}", "Python": "def move_zeroes(nums: list[int]) -> None:\n    write = 0\n    for read in range(len(nums)):\n        if nums[read] != 0:\n            nums[write] = nums[read]\n            write += 1\n    for i in range(write, len(nums)):\n        nums[i] = 0", "Java": "class Solution {\n    public void moveZeroes(int[] nums) {\n        int write = 0;\n        for (int read = 0; read < nums.length; read++) {\n            if (nums[read] != 0) {\n                nums[write] = nums[read];\n                write++;\n            }\n        }\n        for (int i = write; i < nums.length; i++) nums[i] = 0;\n    }\n}", "JavaScript（Node.js）": "function moveZeroes(nums) {\n    let write = 0;\n    for (let read = 0; read < nums.length; read++) {\n        if (nums[read] !== 0) {\n            nums[write] = nums[read];\n            write++;\n        }\n    }\n    for (let i = write; i < nums.length; i++) nums[i] = 0;\n}", "TypeScript": "function moveZeroes(nums: number[]): void {\n    let write = 0;\n    for (let read = 0; read < nums.length; read++) {\n        if (nums[read] !== 0) {\n            nums[write] = nums[read];\n            write++;\n        }\n    }\n    for (let i = write; i < nums.length; i++) nums[i] = 0;\n}"}, "704": {"C#": "public class Solution {\n    public int Search(int[] nums, int target) {\n        int left = 0, right = nums.Length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) return mid;\n            if (nums[mid] < target) left = mid + 1;\n            else right = mid - 1;\n        }\n        return -1;\n    }\n}", "Python": "def search(nums: list[int], target: int) -> int:\n    left, right = 0, len(nums) - 1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] == target:\n            return mid\n        if nums[mid] < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return -1", "Java": "class Solution {\n    public int search(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) return mid;\n            if (nums[mid] < target) left = mid + 1;\n            else right = mid - 1;\n        }\n        return -1;\n    }\n}", "JavaScript（Node.js）": "function search(nums, target) {\n    let left = 0, right = nums.length - 1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) return mid;\n        if (nums[mid] < target) left = mid + 1;\n        else right = mid - 1;\n    }\n    return -1;\n}", "TypeScript": "function search(nums: number[], target: number): number {\n    let left = 0, right = nums.length - 1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) return mid;\n        if (nums[mid] < target) left = mid + 1;\n        else right = mid - 1;\n    }\n    return -1;\n}"}};